function networkError(url, err) {
  if (err.name === 'TimeoutError') {
    return new Error(`Request to ${url.hostname} timed out after ${TIMEOUT_MS / 1000}s`, { cause: err });
  }
  const reason = err.cause?.code ?? err.cause?.message ?? err.message;
  return new Error(`Could not reach ${url.hostname}: ${reason}`, { cause: err });
