async function getJson(url) {
  let res;
  try {
    res = await fetch(url, { signal: AbortSignal.timeout(TIMEOUT_MS) });
  } catch (err) {
    throw networkError(url, err);
  }
  if (!res.ok) {
    // Open-Meteo explains 4xx errors as { error: true, reason }; the body may also be absent or not JSON.
    const reason = await res.json().then((body) => body?.reason, () => undefined);
    const detail = typeof reason === 'string' && reason ? `: ${reason}` : '';
    throw new Error(`Request to ${url.hostname} failed: ${res.status} ${res.statusText}${detail}`);
  }
  try {
    return await res.json();
  } catch (err) {
    if (err.name === 'SyntaxError') {
      throw new Error(`Invalid JSON response from ${url.hostname}`, { cause: err });
    }
    throw networkError(url, err);
  }
}

